import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as i}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Generative Benchmarking","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/evaluation/generative-benchmarking.md","filePath":"zh/tech/evaluation/generative-benchmarking.md","lastUpdated":1780925149000}'),r={name:"zh/tech/evaluation/generative-benchmarking.md"};function s(l,a,d,h,o,c){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="generative-benchmarking" tabindex="-1">Generative Benchmarking <a class="header-anchor" href="#generative-benchmarking" aria-label="Permalink to &quot;Generative Benchmarking&quot;">​</a></h1><blockquote><p>原文: <a href="https://research.trychroma.com/generative-benchmarking" target="_blank" rel="noreferrer">Generative Benchmarking - Chroma</a></p></blockquote><h2 id="背景问题" tabindex="-1">背景问题 <a class="header-anchor" href="#背景问题" aria-label="Permalink to &quot;背景问题&quot;">​</a></h2><p>当前 benchmark 的核心局限：<strong>公开 benchmark 上的强性能并不能直接泛化到真实生产环境</strong>。</p><h3 id="现有-benchmark-的问题" tabindex="-1">现有 Benchmark 的问题 <a class="header-anchor" href="#现有-benchmark-的问题" aria-label="Permalink to &quot;现有 Benchmark 的问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>说明</th></tr></thead><tbody><tr><td><strong>数据集通用性</strong></td><td>泛化数据集无法捕获特定领域的真实用例</td></tr><tr><td><strong>数据过于干净</strong></td><td>与真实数据的混乱性形成对比</td></tr><tr><td><strong>记忆效应</strong></td><td>模型在训练数据中见过 benchmark，导致性能虚高</td></tr></tbody></table><p>这导致一个常见误解：公开 benchmark 上的好成绩 = 生产环境的好表现。</p><h2 id="核心方案-生成式-benchmark" tabindex="-1">核心方案：生成式 Benchmark <a class="header-anchor" href="#核心方案-生成式-benchmark" aria-label="Permalink to &quot;核心方案：生成式 Benchmark&quot;">​</a></h2><p>生成式 Benchmark 针对用户私有数据定制，更准确、更代表真实场景：</p><ul><li>数据集定制到用户文档 → 确保与用例相关</li><li>使用真实混乱数据 → 包含模糊查询</li><li>真正未见过的数据 → 基于用户文档生成，消除记忆可能</li></ul><h2 id="方法论" tabindex="-1">方法论 <a class="header-anchor" href="#方法论" aria-label="Permalink to &quot;方法论&quot;">​</a></h2><h3 id="两步流程" tabindex="-1">两步流程 <a class="header-anchor" href="#两步流程" aria-label="Permalink to &quot;两步流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文档过滤 → 使用对齐的 LLM judge + 用户上下文识别相关文档</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>查询生成 → 使用上下文和示例查询引导生成</span></span></code></pre></div><h3 id="第一步-文档过滤" tabindex="-1">第一步：文档过滤 <a class="header-anchor" href="#第一步-文档过滤" aria-label="Permalink to &quot;第一步：文档过滤&quot;">​</a></h3><p>使用对齐的 LLM judge 评估每个文档是否适合生成查询：</p><p><strong>判断标准</strong>：</p><ul><li><strong>相关性</strong>：文档是否与用例相关</li><li><strong>完整性</strong>：文档是否包含有用信息</li><li><strong>意图</strong>：文档是否适合 ML 用户的使用场景</li></ul><p>通过 5 轮迭代，LLM judge 与人类判断的对齐率从 46% 提升到 75.2%。</p><h3 id="第二步-distinct-query-generation" tabindex="-1">第二步：Distinct Query Generation <a class="header-anchor" href="#第二步-distinct-query-generation" aria-label="Permalink to &quot;第二步：Distinct Query Generation&quot;">​</a></h3><p><strong>核心创新</strong>：将目标文档和 ground truth 查询同时给 LLM，ground truth 作为负面示例，要求生成与之不同的查询。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">基于以下信息：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;document&gt;...&lt;/document&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">这是一个示例查询：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;query&gt;ground truth query&lt;/query&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">请生成一个与示例不同但相关的查询。</span></span></code></pre></div><p><strong>效果</strong>：显著降低 query-query 相似度（从 0.716 → 0.628），同时保持 query-document 相关性分布相似。</p><h2 id="实验验证" tabindex="-1">实验验证 <a class="header-anchor" href="#实验验证" aria-label="Permalink to &quot;实验验证&quot;">​</a></h2><h3 id="公开数据集实验-9-个数据集-5-个-embedding-模型" tabindex="-1">公开数据集实验（9 个数据集，5 个 embedding 模型） <a class="header-anchor" href="#公开数据集实验-9-个数据集-5-个-embedding-模型" aria-label="Permalink to &quot;公开数据集实验（9 个数据集，5 个 embedding 模型）&quot;">​</a></h3><p><strong>关键发现：Naive 生成大量复制了 ground truth</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Wikipedia Multilingual (en):</span></span>
<span class="line"><span>- 11.91% 的生成查询与 ground truth 相似度 &gt; 0.9（几乎相同）</span></span>
<span class="line"><span>- 65.89% 介于 0.6-0.9（轻微改写）</span></span></code></pre></div><h3 id="distinct-生成验证" tabindex="-1">Distinct 生成验证 <a class="header-anchor" href="#distinct-生成验证" aria-label="Permalink to &quot;Distinct 生成验证&quot;">​</a></h3><p><strong>生成的查询是独特的</strong>：</p><ul><li>平均 query-query 相似度显著降低</li><li>在所有数据集和模型上保持一致</li></ul><p><strong>生成的查询具有代表性</strong>：</p><table tabindex="0"><thead><tr><th>指标</th><th>验证方式</th></tr></thead><tbody><tr><td>相对 embedding 模型排名</td><td>Recall@k 排名一致</td></tr><tr><td>Query-Document 分布</td><td>KL 散度低（~0.05-0.2）</td></tr></tbody></table><h2 id="生产环境验证-weights-biases" tabindex="-1">生产环境验证（Weights &amp; Biases） <a class="header-anchor" href="#生产环境验证-weights-biases" aria-label="Permalink to &quot;生产环境验证（Weights &amp; Biases）&quot;">​</a></h2><h3 id="实验设置" tabindex="-1">实验设置 <a class="header-anchor" href="#实验设置" aria-label="Permalink to &quot;实验设置&quot;">​</a></h3><ul><li>数据：WandBot（技术文档支持机器人）的生产查询</li><li>2003 个唯一查询</li><li>13,319 → 8,490 个过滤后的文档</li></ul><h3 id="查询生成方法" tabindex="-1">查询生成方法 <a class="header-anchor" href="#查询生成方法" aria-label="Permalink to &quot;查询生成方法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提供上下文 + 示例查询 → Claude 生成 → 与 ground truth 对比</span></span></code></pre></div><h3 id="关键结果" tabindex="-1">关键结果 <a class="header-anchor" href="#关键结果" aria-label="Permalink to &quot;关键结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Embedding 模型</th><th>Ground Truth Recall@10</th><th>Generated Recall@10</th></tr></thead><tbody><tr><td>text-embedding-3-small</td><td>0.439</td><td>0.530</td></tr><tr><td>text-embedding-3-large</td><td>0.552</td><td>0.602</td></tr><tr><td>jina-embeddings-v3</td><td>0.511</td><td>0.532</td></tr><tr><td>voyage-3-large</td><td>0.670</td><td>0.679</td></tr></tbody></table><p><strong>重要发现</strong>：</p><ul><li>生成查询保持了模型间相对排名</li><li>MTEB 表现与生产环境表现存在差异：jina-embeddings-v3 在 MTEB 上优于 text-embedding-3-large，但在 WandBot 上相反</li></ul><p><strong>这验证了核心论点：公开 benchmark 性能不能直接泛化到真实生产环境。</strong></p><h3 id="消融实验" tabindex="-1">消融实验 <a class="header-anchor" href="#消融实验" aria-label="Permalink to &quot;消融实验&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>KL 散度（与 ground truth）</th></tr></thead><tbody><tr><td>Naive 生成（无上下文）</td><td>0.207</td></tr><tr><td>带上下文和示例生成</td><td><strong>0.159</strong></td></tr></tbody></table><p>上下文和示例对于生成代表性查询至关重要。</p><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ol><li><strong>生产数据集多样性有限</strong>：目前只在 Weights &amp; Biases 数据集上验证</li><li><strong>无匹配文档的查询</strong>：生产中常见的 no-match 场景未被当前指标覆盖</li></ol><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>公开 benchmark 性能与生产性能存在偏差，需要针对性评估</li><li>生成查询时，提供上下文和示例比 naive 生成更能代表真实查询</li><li>通过 document filtering + distinct query generation 流程可生成高质量 benchmark</li><li>Embedding 模型排名在公开 benchmark 和生产环境可能不同</li><li>代码已开源：github.com/chroma-core/generative-benchmarking</li></ul>`,48)])])}const k=t(r,[["render",s]]);export{m as __pageData,k as default};
